function availabilityRoute (value, onebased) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw Error('Invalid device availability route')
  const point = value.online
  if (!point || typeof point.path !== 'string' || !/^\/\/[^\s]{1,1024}$/.test(point.path) ||
    (typeof point.onebased !== 'boolean' && typeof onebased !== 'boolean')) throw Error('Invalid online availability point')
  // Ignore legacy ready metadata: physical online is the sole availability gate.
  return { online: { path: point.path, onebased: point.onebased ?? onebased } }
}

function createDeviceAvailability (routes) {
  const groups = new Map()
  const controls = new Map()
  for (const [id, { binding }] of routes) {
    const keys = new Set()
    for (const meta of [binding.readMeta, binding.writeMeta]) {
      if (!meta?.availability?.online) continue
      const route = availabilityRoute(meta.availability)
      const key = JSON.stringify([binding.device, route])
      if (!groups.has(key)) groups.set(key, { device: binding.device, route, online: false })
      keys.add(key)
    }
    if (keys.size) {
      controls.set(id, [...keys])
    }
  }
  const allowed = id => !controls.has(id) || controls.get(id).every(key => groups.get(key).online === true)
  const snapshot = () => [...controls.keys()].map(id => ({ id, available: allowed(id) }))
  let previous = JSON.stringify(snapshot())
  let dirty = false
  return {
    allowed,
    snapshot,
    invalidateDevice (device) {
      let changed = false
      for (const group of groups.values()) if (group.device === device) {
        if (group.online) changed = true
        group.online = false
      }
      if (changed) dirty = true
      return changed
    },
    changes () {
      if (!dirty) return null
      dirty = false
      const items = snapshot()
      const next = JSON.stringify(items)
      if (next === previous) return null
      previous = next
      return items
    },
    update (message) {
      if (message?.kind !== 'device-availability') return null
      const value = message.payload === true || message.payload === 'true' ? true
        : message.payload === false || message.payload === 'false' ? false : null
      if (value === null) return null
      let changed = false
      for (const group of groups.values()) {
        if (group.device !== message.device) continue
        if (group.route.online.path !== message.path) continue
        if (group.online !== value) changed = true
        group.online = value
      }
      if (!changed) return null
      dirty = true
      return snapshot()
    },
    feedback (items) {
      return items.filter(item => allowed(item.id))
    }
  }
}

module.exports = { availabilityRoute, createDeviceAvailability }
